"""Original curriculum. Examples operate on generated, synthetic evidence."""

from .references import LESSON_PROVENANCE, SOURCE_CATALOG, command_references

SOURCES = [dict(source, id=key) for key, source in SOURCE_CATALOG.items()]


def lesson(id, title, track, minutes, commands, goal, explain, steps, recipe,
           output, fieldwork, adversary, reflection, portability="Uses common POSIX tools on macOS and Linux."):
    return dict(id=id, title=title, track=track, minutes=minutes, commands=commands,
                goal=goal, explain=explain, steps=steps, recipe=recipe, output=output,
                fieldwork=fieldwork, adversary=adversary, reflection=reflection,
                portability=portability, provenance=LESSON_PROVENANCE[id])


